export type ActiveCellState = {
  rowIndex: number
  colIndex: number
  cellId: string | null
}

export type AdapterResult = {
  source: ProposalSource
  title: string
  proposals: ProposalInput[]
  /** Predictions dropped: an index outside the request or the snapshot. */
  dropped: number
}

export type AddInput = {
  source: ProposalSource
  title?: string
  id?: string
  proposals: ReadonlyArray<ProposalInput>
}

export type AdvancedFilterCompileContext<TRow> = {
  /**
   * Resolve a column id to its cell value for a row. The grid passes the same
   * accessor the column-menu filter stage uses, so a `cmp` on a `fieldFn` or
   * value-getter column resolves identically in both.
   */
  getValue: (row: TRow, columnId: string) => unknown
  /** Locale for text folding, matching the column filters. */
  locale?: string | ReadonlyArray<string>
  /**
   * The rows entering this stage. Aggregates (`SUM(amount) > 1000`) are folded
   * over exactly these, once, so they see the rows the user is currently
   * looking at rather than the raw dataset.
   */
  rows: ReadonlyArray<TRow>
}

export type AdvancedFilterEngine = <TRow>(
  expr: GridPredicateExpr,
  ctx: AdvancedFilterCompileContext<TRow>,
) => CompiledRowPredicate<TRow> | null

export type AgendaGroup<TData = unknown> = {
  day: Date
  events: ResolvedEvent<TData>[]
}

export function agendaGroups<TData>(
  events: ReadonlyArray<ResolvedEvent<TData>>,
): AgendaGroup<TData>[]

export type AIAnomaly = {
  /** Index into the SCANNED rows (target order), when the model pins one row. */
  rowIndex?: number
  field?: string
  value?: unknown
  reason: string
  severity: 'low' | 'medium' | 'high'
}

export type AIAnomalyOptions = {
  /** Which rows to scan. Defaults to the whole dataset. */
  target?: AISummarizeTarget
  /** Optional focus, e.g. "look at pricing and margins". */
  question?: string
  signal?: AbortSignal
}

export type AIAnomalyResult = {
  anomalies: AIAnomaly[]
  summary: string
}

export type AIChartExplanation = {
  /** The plain-language reading of the chart (`chartSummary`), as the model saw it. */
  summary: string
  /** Two to three observations the model added: comparisons, outliers, what to look at next. */
  insights: string[]
}

export type AIChartOptions = {
  /** Apply the plan to the grid's chart panel (open + configure). Default false. */
  apply?: boolean
  signal?: AbortSignal
}

export type AIChartPlan = {
  type: AIChartType
  /** Group-by (category-axis) column field, or null. */
  dimension: string | null
  /** Split-by column field: one series per distinct value, or null. */
  series: string | null
  /** Measure (value-axis) column field, or null. */
  measure: string | null
  reduce: AIChartReduce
  stacked: boolean
  logScale: boolean
  timeAxis: boolean
  valueFormat: 'number' | 'currency' | 'percent'
  /** Calendar unit to group a date dimension by, or null for exact values. */
  bucket: 'day' | 'week' | 'month' | 'quarter' | 'year' | null
  /** Candlestick only: indicator panes and overlays to add. */
  indicators?: AIChartIndicator[]
  rationale: string
  /** With `apply`: what `validateChartSpec` flagged as an error on the spec
   *  the panel built from the plan, empty when it drew cleanly. */
  diagnostics?: ChartDiagnostic[]
}

export type AIClassifyOptions = {
  /** Column whose free-text we're classifying. */
  inputField: string
  /** Target column the model should write to. */
  outputField: string
  /** Allowed values. The model is constrained to pick one. */
  classes: string[]
  /** Optional one-line description of each class (acts as a labeling rubric). */
  classDescriptions?: Record<string, string>
  /** Rows to classify. Defaults to all. */
  targetRowIndices?: number[]
  signal?: AbortSignal
}

export type AIClassifyResult = {
  inputField: string
  outputField: string
  predictions: Array<{ rowIndex: number; value: string; confidence: number }>
}

export type AIExplainChartOptions = {
  /** The spec to explain. Default: the grid panel's active chart. */
  spec?: ChartSpec
  signal?: AbortSignal
}

export type AIExportOptions = {
  /**
   * Also apply the filter / sort / grouping to the grid (mutating the view) so
   * it mirrors the export. Default FALSE - the export is self-contained (it
   * computes its own rows), so the grid is left untouched unless you opt in.
   */
  apply?: boolean
  /** Actually download the file. Default true; set false to preview the plan. */
  run?: boolean
  /** Base filename (no extension). Default 'export'. */
  filename?: string
  signal?: AbortSignal
}

export type AIExportPlan = {
  format: ExportFormat
  filters: AIFilterClause[]
  sort: AISortClause[]
  groupBy: string[]
  /** Plain-English explanation of how the model read the request. */
  rationale: string
}

export type AIFilterClause = {
  field: string
  operator: 'contains' | 'equals' | 'startsWith' | 'greaterThan' | 'lessThan' | 'isBlank'
  value?: string
}

export type AIFilterOptions = {
  /**
   * When true, the helper not only RETURNS the plan but also applies it
   * to the grid via `api.setFilter` / `api.setSort`. Defaults to false
   * so callers can show a preview before committing.
   */
  apply?: boolean
  signal?: AbortSignal
}

export type AIFilterResult = {
  filters: AIFilterClause[]
  sort: AISortClause[]
  /** Plain-English explanation of how the model interpreted the query.
   *  Surface this in the UI so the user can confirm or undo. */
  rationale: string
}

export type AIRequest = {
  /** Full prompt the grid built for the model. Already includes column
   *  schema and any sampled rows where applicable. */
  prompt: string
  /** When 'json', the provider should ask the model to return strict
   *  JSON only - no prose. We parse the response with JSON.parse and
   *  throw a typed error on failure. */
  responseFormat?: 'text' | 'json'
  /** Honored if the underlying transport supports cancellation. */
  signal?: AbortSignal
  /** Free-form tag for telemetry / logging. One of: 'filter',
   *  'smart-fill', 'summarize', 'classify'. */
  task: AITask
  /** Soft hint to the provider about how many tokens we expect back.
   *  Useful for routing small jobs to a cheaper model. */
  maxOutputTokens?: number
}

export type AISmartFillOptions = {
  /** Target column - the one whose values we want filled. */
  field: string
  /** Index of rows the model should propose values for. If omitted, every
   *  row whose current `field` value is `null`, `undefined` or `''` is
   *  selected automatically. */
  targetRowIndices?: number[]
  /**
   * Worked examples the user has already filled in. Required - the
   * model needs at least one to know the pattern, two or more to lock
   * the schema. We don't pull these from the grid automatically because
   * "edited" vs "untouched" isn't a state SvGrid exposes today.
   */
  examples: AISmartFillExample[]
  signal?: AbortSignal
}

export type AISmartFillResult<TValue = unknown> = {
  field: string
  predictions: Array<{ rowIndex: number; value: TValue; confidence: number }>
  rationale: string
}

export type AISummarizeOptions = {
  target: AISummarizeTarget
  /** Optional question the user is trying to answer. Helps the model
   *  bias the summary toward the relevant columns. */
  question?: string
  signal?: AbortSignal
}

export type AISummarizeTarget =
  | { kind: 'row'; rowIndex: number }
  | { kind: 'all' }
  | { kind: 'selection'; rowIndices: number[] }
  | { kind: 'group'; field: string; value: unknown }

export type AISummary = {
  text: string
  bullets: string[]
  /** Field names the model thinks are the most load-bearing for the
   *  story it just told. UI can highlight those columns. */
  highlightedFields: string[]
}

export type AppendPointsOptions = {
  /** Keep only the last `window` categories after appending. */
  window?: number
}

export function applyGroupAggregate<TData extends RowData>(
  agg: GroupAggregator<TData>,
  columnId: string,
  rows: ReadonlyArray<Row<TData>>,
): unknown

export function applyRowPredicate<TRow>(
  rows: ReadonlyArray<TRow>,
  keep: (row: TRow) => boolean,
  isGroup: (row: TRow) => boolean,
): TRow[]

export type AutoHideEntry = {
  id: string
  side: DockSide
  leaf: DockTabs
  /** Fly-out panel size in px along the reveal axis. */
  size: number
}

export function autoHideLeaf(
  state: DockManagerState,
  tabsId: string,
  side: DockSide,
  size = 260,
): DockManagerState

export function autoMapColumns(
  headers: string[],
  columns: ReadonlyArray<ImportGridColumn>,
): ImportColumnMap

export function axisScale(
  dataMin: number,
  dataMax: number,
  axis: { min?: number; max?: number; nice?: boolean; tickCount?: number; tickInterval?: number } = {},
): NiceScale

export const BASE_ROW_METHODS = {
  getCanExpand(this: BaseRowState<RowData>) {
    return false
  },
  getIsExpanded(this: BaseRowState<RowData>) {
    return Boolean((this[ROW_CTX].store.state.expanded ?? {})[this.id])
  },
  toggleExpanded(this: BaseRowState<RowData>) {
    const id = this.id
    this[ROW_CTX].grid.setExpanded((prev) => ({ ...prev, [id]: !prev[id] }))
  },
  getIsSelected(this: BaseRowState<RowData>) {
    return Boolean((this[ROW_CTX].store.state.rowSelection ?? {})[this.id])
  },
  toggleSelected(this: BaseRowState<RowData>) {
    const id = this.id
    this[ROW_CTX].grid.setRowSelection((prev) => ({ ...prev, [id]: !prev[id] }))
  },
  getAllCells(this: BaseRowState<RowData>) {
    return this[ROW_CELLS] ?? buildBaseRowCells(this)
  },
  getCellValueByColumnId(this: BaseRowState<RowData>, columnId: string) {
    const idx = this[ROW_CTX].columnIndexById.get(columnId)
    if (idx === undefined) return undefined
    if (!this[ROW_VALUES]) this[ROW_VALUES] = baseRowValues(this)
    return this[ROW_VALUES][idx]
  },
}

export type BaseRowCtx<TData extends RowData> = {
  grid: SvGrid<TData>
  store: { state: Record<string, any> }
  columns: Array<Column<TData>>
  columnCount: number
  columnIndexById: Map<string, number>
}

export function binValues(
  values: ReadonlyArray<number>,
  opts: { bins?: number; binWidth?: number; method?: 'sturges' | 'fd' | 'sqrt'; min?: number; max?: number } = {},
): ChartBins

export type BlockCacheState = {
  /** Rows after filtering, or `null` while the backend has not said. */
  rowCount: number | null
  /** False while the end of the data is still being discovered. */
  lastRowKnown: boolean
  /** True while at least one block is in flight. */
  loading: boolean
  /** Blocks whose fetch rejected. Empty unless something went wrong. */
  failedBlocks: number[]
}

export type BlockFetchResult<TData> = {
  rows: ReadonlyArray<TData>
  /**
   * Total rows after filtering. Omit it (or send `-1`) when the backend cannot
   * count cheaply - the cache then discovers the end from the first short
   * block, and `lastRowKnown()` stays false until it does.
   */
  rowCount?: number
}

export type BlockState = {
  blockIndex: number
  startRow: number
  endRow: number
  status: 'loading' | 'loaded' | 'failed'
  /** Monotonic counter of when the viewport last covered this block. */
  lastTouched: number
}

export type BorderSpec = {
  /** Thickness in pixels. Default 2. */
  width?: number
  /** CSS border-style. Default 'solid'. */
  style?: 'solid' | 'dashed' | 'dotted' | 'double'
  /** CSS color. Falls back to currentColor (i.e. text color). */
  color?: string
}

export type BoxStats = {
  min: number
  q1: number
  median: number
  q3: number
  max: number
  /** Values outside the whiskers, drawn as individual points. */
  outliers?: number[]
}

export function bucketsToChartSpec(
  buckets: ReadonlyArray<{ category: string; series?: string; value: number }>,
  type: ChartType,
  hasSeries: boolean,
): ChartSpec

export function buildChartPdf(
  jpeg: { bytes: Uint8Array; width: number; height: number },
  opts: Pick<ChartPdfOptions, 'page' | 'orientation' | 'title' | 'subtitle' | 'caption'> = {},
): Uint8Array

export function buildGroupedPdfBody<TData extends RowData>(
  cols: ReadonlyArray<ExportColumn<TData>>,
  rows: ReadonlyArray<TData>,
  groupBy: ReadonlyArray<string>,
): PdfBodyRow[]

export function buildLinePath(
  pts: Array<{ x: number; y: number; defined: boolean }>,
  smooth: boolean,
  opts: { connectNulls?: boolean; step?: Step } = {},
): string

export function buildLinkResolver<TData extends RowData>(
  cols: ReadonlyArray<ExportColumn<TData>>,
  rows: ReadonlyArray<TData>,
): ((rowIdx: number, colIdx: number) => string | undefined) | undefined

export function buildPivotResultColumns(
  fields: ReadonlyArray<string>,
  aggregations: ReadonlyArray<ServerAggregation>,
  options: PivotResultColumnOptions = {},
): Array<ColumnDef<any, any>>

export type CallbackDatasource<TData = unknown> = {
  getRows(params: CallbackGetRowsParams<TData>): void
  destroy?(): void
}

export type CallbackGroupSelectionState = {
  nodeId?: string
  selectAllChildren?: boolean
  toggledNodes?: CallbackGroupSelectionState[]
}

export type CallbackSelectionState = {
  selectAll: boolean
  /** Exceptions to `selectAll`, as row ids. */
  toggledNodes: string[]
}

export type CellEditorRegistration = {
  /** The Svelte component to mount in the editing cell. */
  component: Component<any>
  /**
   * Map the editing context to the component's props. Defaults to
   * {@link defaultEditorProps} (value + onChange/onCommit/onCancel).
   */
  props?: (ctx: CellEditorContext) => Record<string, unknown>
  /** Hint that the editor should open its popover immediately on mount. */
  autoOpen?: boolean
  /**
   * Whether typing on a selected cell starts this editor with the typed
   * character (`typed: true` on the context). A function decides per key,
   * e.g. digits only for a number editor. Default: every printable key.
   */
  typeToEdit?: boolean | ((char: string) => boolean)
}

export type CellFormatConfig =
  | {
      type: 'number'
      locales?: string | Array<string>
      options?: Intl.NumberFormatOptions
    }
  | {
      type: 'currency'
      /** ISO 4217 (default USD) */
      currency?: string
      locales?: string | Array<string>
      options?: Omit<Intl.NumberFormatOptions, 'style' | 'currency'>
    }
  | {
      type: 'percent'
      locales?: string | Array<string>
      options?: Omit<Intl.NumberFormatOptions, 'style'>
      /**
       * If true, numeric cell values are 0–100 (e.g. 42 → 42%) instead of Intl’s 0–1 fraction (0.42 → 42%).
       * Default false.
       */
      valueIsPercentPoints?: boolean
    }
  | {
      type: 'date' | 'datetime'
      locales?: string | Array<string>
      /**
       * Shortcut patterns merged with `options`:
       * `'d'` short numeric date, `'D'` long date, `'y-m-d'` yyyy/mm/dd-style,
       * `'short'`|`'medium'`|`'long'` use dateStyle/timeStyle presets.
       */
      pattern?: string
      options?: Intl.DateTimeFormatOptions
    }

export type CellFormatter<TData extends RowData> = (context: {
  value: unknown
  row: Row<TData>
  column: Column<TData>
  table: SvGrid<TData>
}) => string

export type CellSpanParams<TData extends RowData = RowData> = {
  /** The row's underlying data object. */
  data: TData
  /** Display-row index in the current (filtered/sorted) row set. */
  rowIndex: number
  /** The column's id. */
  columnId: string
  /** The cell's base value for this column. */
  value: unknown
}

export const CHART_RESPONSIVE_PRESETS = {
  compact: (maxWidth: number): ChartResponsiveRule => ({
    maxWidth,
    spec: { seriesLabels: false, dataLabels: { show: false }, xAxis: { labelRotation: 90 } },
    legend: false,
  }),
} as const

export type ChartAnimateConfig = {
  /** Tween length in ms. Default 400. */
  duration?: number
  /** How marks first appear: fade (default), grow from the baseline, or wipe
   *  left to right. `'none'` draws them in place. */
  enter?: 'fade' | 'grow' | 'wipe' | 'none'
  /** Slide marks to their new positions when the data changes. Default true
   *  when `animate` is set at all. */
  update?: boolean
}

export type ChartAnnotation = {
  /** Anchor in data space. Provide either `category` + `axis` for a point on
   *  an existing series, OR raw `x` / `y` numeric coordinates in data space. */
  at:
    | { category: string; series?: string }
    | { x: number; y?: number }
  label: string
  color?: string
  /** Where the label sits relative to the marker. Defaults to 'top'. */
  placement?: 'top' | 'bottom' | 'left' | 'right'
  /** The marker: a small `'dot'` (default), a `'flag'` on a pole, a map
   *  `'pin'`, or a `'square'`. Flags and pins carry the label INSIDE the
   *  marker, the way earnings and dividend flags read on a price chart. */
  shape?: 'dot' | 'flag' | 'pin' | 'square'
  /** Longer text shown in a tooltip when the marker is hovered or focused. */
  text?: string
}

export type ChartArc = {
  path: string
  color: string
  textColor: string
  /** Category (radial bar / column, nightingale, chord group) or node name (sunburst). */
  label: string
  series: string
  value: number
  /** Start / end angle in radians, 12 o'clock = -PI/2, clockwise. */
  a0: number
  a1: number
  /** Inner / outer radius. */
  r0: number
  r1: number
  cx: number
  cy: number
  /** Sunburst depth from the root (0 = first ring). */
  depth?: number
  /** Sunburst: the path of node names from the root, for drilldown. */
  nodePath?: string[]
  /** Centroid, for a label. */
  lx: number
  ly: number
  /** Radial bar: the faint full ring behind the value arc. */
  trackPath?: string
}

export type ChartAxisConfig = {
  /** Pin the low end of the domain. The data still stretches it if a value
   *  falls outside, unless `nice` is false. */
  min?: number
  /** Pin the high end of the domain. */
  max?: number
  /** Round the domain out to tick boundaries. Default true. `false` uses the
   *  exact data extent (or `min` / `max`). */
  nice?: boolean
  /** Approximate number of ticks. Default 4. */
  tickCount?: number
  /** Exact spacing between ticks, in data units. Beats `tickCount`. */
  tickInterval?: number
  /** Number format for this axis' labels. Defaults to the spec `valueFormat`. */
  format?: ChartValueFormat
  /** Full control over each tick label. Beats `format`. */
  formatter?: (value: number, index: number) => string
  /** Axis title. Mirrors `xAxisTitle` / `yAxisTitle` / `y2AxisTitle`. */
  title?: string
  /** Draw grid lines across the plot at each tick. Default true for the left
   *  value axis, false for the x and right axes. */
  gridLines?: boolean
  /** Category-label rotation in degrees. `'auto'` (default) rotates -40 when
   *  labels are long or many; `0` never rotates. */
  labelRotation?: number | 'auto'
  /** Run the axis the other way: values decrease upward (or rightward). */
  reversed?: boolean
  /** Value axes (mirrors `yScale` / `y2Scale`), and a `type: 'number'` x
   *  axis: `'log'` spaces decades evenly, labels them, and drops categories
   *  at or below zero. */
  scale?: 'linear' | 'log'
  /** X axis only. Mirrors `xType`. `'number'` parses each category as a number
   *  and positions marks by value, so `['1', '2', '10']` spreads out. */
  type?: 'category' | 'time' | 'ordinal-time' | 'number'
  /** Fixed gutter width in px for a value axis, so stacked charts (panes)
   *  share one left edge. Default: measured. */
  width?: number
  /** Draw the tick labels. Default true. `false` keeps the ticks and grid
   *  lines but hides the text - what a pane above another pane wants. */
  labels?: boolean
}

export type ChartBar = {
  x: number
  y: number
  w: number
  h: number
  color: string
  /** Category (x label) this bar belongs to - for tooltips + labels. */
  label: string
  /** Series label this bar belongs to. */
  series: string
  value: number
  /** Category index. A grouped axis repeats its leaf labels (Q1 to Q4 under
   *  each year), so the label alone cannot name one bar; this can. */
  index?: number
  /** Series opacity, when the series set one. */
  opacity?: number
  /** The low end of a floating (range) bar, when it does not sit on the axis. */
  lo?: number
}

export type ChartBins = {
  /** Bin midpoints as strings, ready to be the categories of a numeric axis. */
  categories: string[]
  /** Observations per bin. */
  counts: number[]
  /** Bin edges, one more than there are bins. */
  edges: number[]
  /** Width of every bin. */
  width: number
}

export type ChartCalendarCell = {
  x: number
  y: number
  size: number
  date: string
  value: number
  /** Defined when a value was supplied for this day; blank otherwise. */
  defined: boolean
  color: string
}

export type ChartContextTarget = {
  category?: string
  index?: number
  series?: string
  value?: number
}

export type ChartDataLabel = {
  x: number
  y: number
  text: string
  anchor: 'start' | 'middle' | 'end'
  onBar: boolean
  series: string
  /** Rotation in degrees about (x, y), from `dataLabels.rotation`. */
  angle?: number
  /** A leader from the mark to a label that was pushed away from it. */
  leader?: { x1: number; y1: number; x2: number; y2: number }
}

export type ChartDataLabelConfig = {
  /** Draw the labels at all. Default true when the object is given. */
  show?: boolean
  /** Where a label sits on its mark. `'top'` above a bar / point (default),
   *  `'inside'` centred in the bar, `'outside'` past the end of a horizontal
   *  bar, `'center'` at the mark's centre. */
  placement?: 'top' | 'inside' | 'outside' | 'center'
  /** Custom label text. Beats the value format. */
  formatter?: (value: number, ctx: { category: string; series: string }) => string
  /** Hide labels that would overlap an earlier one. Default true. */
  hideOverlap?: boolean
  /** Rotate every label by this many degrees about its anchor (`-45` reads
   *  up and to the right). The overlap test uses the rotated box. */
  rotation?: number
  /** Instead of hiding a label that would overlap, push it away from its mark
   *  (up on a vertical chart, right on a horizontal one) until it is clear,
   *  and draw a leader line from the mark to it. Labels that cannot find
   *  room within four steps are dropped. Default false. */
  connector?: boolean
}

export type ChartDecimateConfig =
  | boolean
  | 'auto'
  | {
      /** `'lttb'` (default) keeps the visual shape; `'minmax'` keeps every
       *  extreme in each pixel bucket, which suits spiky monitoring data. */
      method?: 'lttb' | 'minmax'
      /** Points to keep. Default: the plot width in px. */
      target?: number
      /** Only decimate above this many points. Default: `target`. */
      threshold?: number
    }

export type ChartDiagnostic = {
  /** A stable rule id, `chart/<rule>`. */
  code: string
  /** The field's path in the spec, like `series[1].values` or `yAxis.min`. */
  path: string
  message: string
  /** `error`: will not draw as intended. `warning`: ignored, or a likely slip. */
  severity: 'error' | 'warning'
}

export type ChartDrawingGeo = {
  id: string
  kind: ChartDrawingKind
  points: Array<{ x: number; y: number }>
  color: string
  text?: string
  /** Fibonacci levels between the two points, top to bottom. */
  levels?: Array<{ ratio: number; y: number; label: string }>
  /** The label a horizontal ray carries at the axis: its value. */
  label?: string
}

export type ChartExportOptions = {
  /** Background color of the exported image. Default: the grid background. */
  background?: string
  /** PNG pixel scale (1 = viewBox size). Default 2 (retina). */
  scale?: number
}

export type ChartFormatState = {
  title?: string
  subtitle?: string
  caption?: string
  /** Where the legend goes; `false` hides it. The panel reads this for the
   *  component prop, it is not a spec field. */
  legend?: 'top' | 'bottom' | 'left' | 'right' | false
  xAxis?: { title?: string; gridLines?: boolean; labelRotation?: number | 'auto' }
  yAxis?: { min?: number | null; max?: number | null; title?: string; gridLines?: boolean; format?: ChartValueFormat }
  y2Axis?: { min?: number | null; max?: number | null; title?: string; gridLines?: boolean; format?: ChartValueFormat }
  /** Per-series overrides, keyed by series label. */
  series?: Record<string, {
    color?: string
    type?: 'bar' | 'line' | 'area'
    axis?: 'left' | 'right'
    marker?: ChartMarkerShape
    strokeWidth?: number
    dash?: string
    smooth?: boolean
    /** The stack group a bar or area joins; an empty string leaves the
     *  group. See {@link ChartSeries.stack}. */
    stack?: string
  }>
  /** Where data labels sit; `null` hides them. */
  dataLabels?: 'inside' | 'outside' | 'top' | 'center' | null
  palette?: string[] | null
  /** Series names at the end of each line (`spec.seriesLabels`). */
  seriesLabels?: boolean
  /** The axis value pills on the crosshair. A component prop, like
   *  `legend`: the panel reads it, the engine does not. */
  crosshairLabels?: boolean
  /** Below this rendered width in px the chart goes compact: no series or
   *  data labels, vertical category labels, no legend. Appended to the
   *  spec's own `responsive` rules as {@link CHART_RESPONSIVE_PRESETS}.compact. */
  compactBelow?: number | null
  /** Font, size and colours for the whole chart (`spec.style`), merged
   *  over what the spec carries. */
  style?: ChartStyle
}

