  groupId?: (route: string[]) => string
  /** The group key for a node id under `parentRoute`. Default: the id itself. */
  groupKey?: (nodeId: string, parentRoute: string[]) => string
  /**
   * Whether the node `nodeId` under `parentRoute` is a group row. Default:
   * it is when it carries exceptions of its own, a leaf otherwise. A flipped
   * group read as a leaf still selects the same rows; only `selectedCount`
   * is off, since a group exception has no size of its own.
   */
  isGroup?: (nodeId: string, parentRoute: string[]) => boolean
}

export type ServerDetailRow<TData> = {
  kind: 'detail'
  id: string
  level: number
  route?: string[]
  /** The leaf's id, as `getRowId` names it. */
  masterId: string
  master: TData
}

export type ServerFooterRow<TData> = {
  kind: 'footer'
  id: string
  level: number
  path: string[]
  /** The group this footer totals (its key). */
  key: string
  aggregates: Record<string, unknown>
  /** The group's response row (key + aggregates), so value columns show totals. */
  data: TData
}

symbols.doc:
A group row in the server-side group/tree model - one distinct key at a
level, with its rolled-up aggregates. The grid renders it with an expander;
expanding it fetches its children through the same `getRows`.

symbols.signature:
export type ServerGroupRow<TData> = {
  kind: 'group'
  /** Stable id (the group path). */
  id: string
  /** Group keys from the root to this node, e.g. `['Germany', 'Berlin']`. */
  path: string[]
  /** The column this group is on (the `groupBy` entry for this level). */
  field: string
  /** This group's key value. */
  key: string
  /** Zero-based depth (0 = top level). */
  level: number
  expanded: boolean
  loading: boolean
  /** Aggregate values keyed by column id, read from the group's response row. */
  aggregates: Record<string, unknown>
  /**
   * How many rows this group holds, when the backend said (see the row
   * model's `childCount` option). Drawn next to the key by `SvGroupCell`,
   * and used to size the group's scrollbar before its first block lands.
   */
  childCount?: number
  /**
   * `false` when nothing can open beneath this row: the innermost group
   * level under a server-side pivot, whose rows are the result itself.
   * The group cell then draws no expander.
   */
  expandable?: boolean
  /** The raw response row for this group (key + aggregates), for cell rendering. */
  data: TData
}

export type ServerGroupSelectionNode = {
  /** Whether everything under this node is selected, before exceptions. */
  selectAllChildren: boolean
  /** Exceptions, keyed by child id (a group key or a leaf id) under this node. */
  toggled: Record<string, ServerGroupSelectionNode>
  /**
   * True when this node is a group. A flipped group is an exception of
   * unknown size (its rows were never counted here); a flipped leaf is
   * exactly one row. Absent on the root and on leaves.
   */
  group?: boolean
}

export function serverGroupText<TData>(
  row: ServerRowModelGridRow<TData>,
  leafField?: keyof TData & string,
  messages?: Partial<ServerGroupMessages>,
): string

export type ServerLeafRow<TData> = {
  kind: 'leaf'
  id: string
  level: number
  /** The group path this leaf sits under. Set by the block-cached row model. */
  route?: string[]
  data: TData
}

export type ServerMoreRow = {
  kind: 'more'
  id: string
  level: number
  /** Path of the parent group whose children to load more of. */
  path: string[]
  /** How many children remain unloaded. */
  remaining: number
  loading: boolean
}

export type ServerPlaceholderRow = {
  readonly kind: 'placeholder'
  readonly state: 'loading' | 'failed'
}

export type ServerRowModelGridRow<TData> = (TData | Record<string, never>) & {
  __group: ServerRowModelDisplayRow<TData>
}

export type ServerRowModelPagination = {
  pageIndex: number
  pageSize: number
  /** Top-level rows, or flattened rows with `paginateChildRows`. */
  rowCount: number
  pageCount: number
}

export type ServerRowModelPaginationOptions = {
  /** Rows per page. Default 100. */
  pageSize?: number
  /** Choices for the footer's page-size selector. */
  pageSizes?: number[]
  /**
   * Fit the page to the grid: as many rows as its body shows without
   * scrolling, re-measured when the grid resizes. `pageSize` is then the
   * size until the first measurement.
   */
  autoPageSize?: boolean
  /**
   * Count every row of the flattened tree towards the page, children
   * included. Off, a page is `pageSize` top-level rows, each shown with
   * whatever is open beneath it.
   */
  paginateChildRows?: boolean
}

export function serverRowModelRows<TData>(
  state: ServerRowModelState<TData> | null | undefined,
): ReadonlyArray<ServerRowModelGridRow<TData>>

export type ServerRowModelState<TData> = {
  /**
   * The flattened tree, one entry per row the grid shows: groups with their
   * expanded children spliced in, footers, the grand total, and a shared
   * placeholder object for every row not yet loaded.
   */
  displayRows: ReadonlyArray<ServerRowModelDisplayRow<TData>>
  /** `displayRows` mapped to grid rows - each row's data spread, plus `__group`. */
  gridRows: ReadonlyArray<ServerRowModelGridRow<TData>>
  groupBy: string[]
  aggregations: ServerAggregation[]
  /** Rows at the top level, or null until the root has answered. */
  rowCount: number | null
  /** True while the root has never loaded. */
  loading: boolean
  /** True while a `createRow`, `updateRow` or `deleteRow` is in flight. */
  saving: boolean
  /** The rejection from the last failed top-level fetch, else null. */
  error: unknown
  sortModel: ServerSortModel
  filterModel: ServerFilterModel
  /** Ids (JSON of the route) of the expanded groups. */
  expandedGroups: string[]
  /** Ids (by `getRowId`) of the leaves whose detail panel is open. */
  openDetails: string[]
  /** The grand-total row, when one is configured and has arrived. */
  grandTotal: TData | null
  pivotBy: string[]
  pivotMode: boolean
  /** The pivoted value fields the backend has reported so far, in pivot mode. */
  pivotResultFields: string[]
  /** The pager, or null when the top level scrolls. */
  pagination: ServerRowModelPagination | null
}

export type ServerSelectionModelOptions = {
  /**
   * How ticking a group row behaves. `self` selects that one row;
   * `descendants` selects everything beneath it. `filteredDescendants` is
   * `descendants` under a filter, which on a server is the same rule - the
   * server applies the filter - so it is accepted as an alias.
   */
  groupSelects?: ServerSelectionGroupMode
  /** Called after any change. The row model re-renders from here. */
  onChange?: () => void
  /**
   * How many leaves sit under a group, by its route, or `null` when that is
   * not known. `selectedCount` needs it once a rule flips a whole group
   * (a plan ticked under an unticked root): without it the count of such a
   * rule is unknown. The row model answers from the group row's `count`
   * aggregate.
   */
  leafCount?: (route: ReadonlyArray<string>) => number | null
}

export type ServerSelectionRule =
  | { selectAll: boolean; toggled: string[] }
  | {
      selectAllChildren: boolean
      toggled: Record<string, { selectAllChildren: boolean; toggled: Record<string, unknown>; group?: boolean }>
      group?: boolean
      /** The group columns the tree's levels are keyed by, outer to inner. */
      groupBy?: string[]
    }

export type ServerSelectionState = {
  selectAll: boolean
  /** Exceptions to `selectAll`: selected ids when it is false, deselected ones when true. */
  toggled: string[]
}

export type ServerSkeletonRow = {
  kind: 'skeleton'
  id: string
  level: number
}

export type ServerTransaction<TData> = {
  /** The level to apply to. Omit for the top level. */
  route?: string[]
  add?: ReadonlyArray<TData>
  /** Where `add` goes. Default: the end of the level. */
  addIndex?: number
  update?: ReadonlyArray<TData>
  /** Rows to remove, or their ids. */
  remove?: ReadonlyArray<TData | string>
  /**
   * The level's row count afterwards, when you know it better than the
   * arithmetic does - a delete that also removed rows outside the cache,
   * say. Applied last.
   */
  rowCount?: number
}

export type ServerTransactionResult = {
  status: ServerTransactionStatus
  /** Ids of the rows placed in the cache. */
  add: string[]
  /** Ids of the rows found and updated. */
  update: string[]
  /** Ids of the rows found and removed. */
  remove: string[]
}

